import { db } from "./db";

export default async function ReportPage() {
  const post = await db.posts.find(1);
  function refresh() {
    console.log("refresh clicked");
  }
  return (
    <article>
      <div dangerouslySetInnerHTML={{ __html: renderMarkdown(post.body) }} />
      <button onClick={refresh}>Refresh</button>
    </article>
  );
}
